$fn = 96;

beam_length       = 180;
beam_height       = 60;
flange_width      = 36;
flange_thickness  = 8;
web_thickness     = 7;
web_height        = beam_height - 2 * flange_thickness;

module i_beam_profile() {
  union() {
    translate([0, 0, beam_height/2 - flange_thickness/2])
      cube([beam_length, flange_width, flange_thickness], center = true);
    translate([0, 0, -(beam_height/2 - flange_thickness/2)])
      cube([beam_length, flange_width, flange_thickness], center = true);
    cube([beam_length, web_thickness, web_height], center = true);
  }
}

i_beam_profile();

$fn = 48;

beam_length = 180;
beam_height = 80;
flange_width = 44;
flange_thickness_outer = 6;
flange_thickness_inner = 10;
web_thickness = 6;
web_height = beam_height - 2 * flange_thickness_inner;

module tapered_flange_i_beam() {
  union() {
    linear_extrude(height = beam_length, center = true)
      polygon(points=[[-flange_width/2, beam_height/2-flange_thickness_outer], [flange_width/2, beam_height/2-flange_thickness_outer], [web_thickness/2, beam_height/2-flange_thickness_inner], [-web_thickness/2, beam_height/2-flange_thickness_inner]]);
    linear_extrude(height = beam_length, center = true)
      polygon(points=[[-flange_width/2, -beam_height/2+flange_thickness_outer], [flange_width/2, -beam_height/2+flange_thickness_outer], [web_thickness/2, -beam_height/2+flange_thickness_inner], [-web_thickness/2, -beam_height/2+flange_thickness_inner]]);
    cube([web_thickness, web_height, beam_length], center=true);
  }
}

tapered_flange_i_beam();

$fn = 48;

beam_length = 180;
beam_height = 80;
flange_width = 42;
flange_thickness = 7;
web_thickness = 5;
web_height = beam_height - 2 * flange_thickness;

module narrow_flange_i_beam() {
  union() {
    translate([0, beam_height/2 - flange_thickness/2, 0]) cube([flange_width, flange_thickness, beam_length], center=true);
    translate([0, -beam_height/2 + flange_thickness/2, 0]) cube([flange_width, flange_thickness, beam_length], center=true);
    cube([web_thickness, web_height, beam_length], center=true);
  }
}

narrow_flange_i_beam();

